-- m176: اصلاحات عددی بازبینی بیرونی (طرح نسخهٔ ۲ «ساعت» — بستهٔ الف) + پاک‌سازی واژگان فنی از متن درمانگر
-- SNAP-IV والد: نافرمانی ۱٫۴۷→۱٫۸۸ (Swanson 2001/Bussing 2008)؛ SCARED: اجتماعی ۶→۸، مدرسه ۱→۳ (قواعد در rules.ts)؛
-- DCDQ: باند مرزی همه‌سنی → باندهای محتاطانهٔ ۳۱/۴۲/۶۰ با راهنمای سنی؛ SDQ: چهارباندی رسمی به‌تفکیک گزارش‌دهنده
-- ثابت: کلیدها، فیلدها، مقیاس‌ها، زیرمقیاس‌ها (جز نام مدرسه)، منطق موتور استنتاج
UPDATE case_event_types SET subscales = '[{"id": "ia", "name": "توجه و پیگیری کارها", "bands": [{"max": 16, "label": "در محدودهٔ عادی", "color": "ok"}, {"max": 21, "label": "مرزی — نیاز به بررسی", "color": "warn", "advice": "نمرهٔ توجه مرزی است؛ فرم معلم را هم بگیرید و مقایسه کنید."}, {"max": 9999, "label": "قابل توجه — نیاز به بررسی بیشتر", "color": "danger", "advice": "کم‌توجهی بالاتر از حد انتظار والد گزارش شده؛ فرم معلم + ملاک‌های DSM لازم است."}]}, {"id": "hi", "name": "بی‌قراری و تندمزاجی", "bands": [{"max": 12, "label": "در محدودهٔ عادی", "color": "ok"}, {"max": 16, "label": "مرزی — نیاز به بررسی", "color": "warn"}, {"max": 9999, "label": "قابل توجه — نیاز به بررسی بیشتر", "color": "danger", "advice": "بی‌قراری/تکانشگری بالاتر از حد انتظار والد؛ ارزیابی چندمرجعی پیشنهاد می‌شود."}]}, {"id": "odd", "name": "لجبازی و نافرمانی", "bands": [{"max": 15, "label": "در محدودهٔ عادی", "color": "ok"}, {"max": 19, "label": "مرزی — نیاز به بررسی", "color": "warn", "advice": "نافرمانی کمی بالاتر از حد معمول است؛ چک‌لیست ملاکی ODD برای تفکیک دقیق‌تر پیشنهاد می‌شود."}, {"max": 9999, "label": "قابل توجه — نیاز به بررسی بیشتر", "color": "danger", "advice": "نافرمانی بالاست؛ چک‌لیست ملاکی ODD برای تفکیک از بی‌قراریِ تکانشی پیشنهاد می‌شود."}]}]',
